  "private": true,
  "type": "module",
  "scripts": {
    "test": "node --test --test-isolation=none test/checkout-total.test.mjs"
  }
}

import test from 'node:test';
import assert from 'node:assert/strict';

import { calculateCheckoutTotal } from '../src/checkout-total.mjs';

test('preserves fractional cents until the final total is rounded', () => {
  const items = [
    { price: 0.335, quantity: 3 },
    { price: 0.335, quantity: 3 },
  ];
  assert.equal(calculateCheckoutTotal(items), 2.01);
});

export function roundCurrency(value) {
  return Math.round((value + Number.EPSILON) * 100) / 100;
}

export function calculateCheckoutTotal(items, taxRate = 0) {
  const subtotal = items.reduce(
    (total, item) => total + roundCurrency(item.price * item.quantity),
    0,
  );
  return roundCurrency(subtotal * (1 + taxRate));
}

export function applyDiscount(amount, percentage) {
  return amount * (1 - percentage / 100);
}

export function shippingCost(weightKg) {
  return weightKg <= 2 ? 4.99 : 9.99;
}

export function calculateTax(amount, rate) {
  return Math.round(amount * rate * 100) / 100;
}
